/**
 * UIKEY LABS — Production Frontend Module v7.0
 * - Centralized Campaign Config Constant (`window.UIKEY_CONFIG`: Fixed Deadline Date & 7/10 Slot Count)
 * - Fixed Real-Date Countdown (No milliseconds, never resets on reload, 0 state after expiry)
 * - Universal UPI QR Code Generator (`window.QRCode` + `updateStandeeQr`)
 * - Flag-Only 360px Mobile Language Toggle (EN / HI)
 * - Accessible Mobile Navigation Drawer & Consultation Lead Handler
 */
(function () {
  "use strict";

  /* 1. Single Centralized Campaign & Slot Configuration Constant (Used Everywhere) */
  var UIKEY_CONFIG = Object.freeze({
    DEADLINE_ISO: "2026-10-31T23:59:59+05:30",
    SLOTS_CLAIMED: 7,
    SLOTS_TOTAL: 10,
    WHATSAPP_NUMBER: "918770912734",
    PHONE_DISPLAY: "+91 87709 12734",
    EMAIL: "contact@uikeylabs.com",
    PAGESPEED_REPORT_URL: "https://pagespeed.web.dev/analysis?url=https%3A%2F%2Fuikeylabs.com%2F"
  });
  window.UIKEY_CONFIG = UIKEY_CONFIG;

  var currentLang = "en";

  /* 2. Fixed-Date Campaign Countdown & Unified Slot Counter (No Milliseconds, 0 State on Expiry) */
  function pad2(n) {
    return n < 10 ? "0" + n : String(n);
  }

  function renderCampaignSlotsAndTimer() {
    var remainingSlots = Math.max(0, UIKEY_CONFIG.SLOTS_TOTAL - UIKEY_CONFIG.SLOTS_CLAIMED);
    var slotText =
      UIKEY_CONFIG.SLOTS_CLAIMED +
      "/" +
      UIKEY_CONFIG.SLOTS_TOTAL +
      " Slots Claimed (" +
      remainingSlots +
      " Left)";

    var slotNodes = document.querySelectorAll("[data-slots-text]");
    slotNodes.forEach(function (node) {
      node.textContent = slotText;
    });

    var deadlineMs = new Date(UIKEY_CONFIG.DEADLINE_ISO).getTime();
    var nowMs = Date.now();
    var diffSec = Math.floor((deadlineMs - nowMs) / 1000);

    var timerNodes = document.querySelectorAll("[data-campaign-countdown]");
    if (isNaN(deadlineMs) || diffSec <= 0) {
      timerNodes.forEach(function (node) {
        node.textContent = "00d : 00h : 00m : 00s (Offer Ended)";
      });
      return;
    }

    var days = Math.floor(diffSec / 86400);
    var hours = Math.floor((diffSec % 86400) / 3600);
    var minutes = Math.floor((diffSec % 3600) / 60);
    var seconds = diffSec % 60;

    var formatted = pad2(days) + "d : " + pad2(hours) + "h : " + pad2(minutes) + "m : " + pad2(seconds) + "s";
    timerNodes.forEach(function (node) {
      node.textContent = formatted;
    });
  }

  /* 3. Universal QR Code Renderer (Works with qrcode.min.js SVG + fallback image on all devices) */
  if (typeof window.QRCode === "undefined") {
    window.QRCode = function (el, opts) {
      if (typeof el === "string") el = document.getElementById(el);
      if (!el) return;
      var txt = typeof opts === "string" ? opts : (opts && opts.text ? opts.text : "https://uikeylabs.com");
      var size = opts && opts.width ? opts.width : 205;
      try {
        if (typeof window.qrcode === "function") {
          var qr = window.qrcode(0, "M");
          qr.addData(txt);
          qr.make();
          el.innerHTML = qr.createSvgTag({ cellSize: 5, margin: 2, scalable: true });
          var svgEl = el.querySelector("svg");
          if (svgEl) {
            svgEl.style.width = "100%";
            svgEl.style.height = "100%";
            svgEl.style.maxWidth = size + "px";
            svgEl.style.maxHeight = size + "px";
            svgEl.style.display = "block";
            svgEl.style.margin = "0 auto";
          }
          return;
        }
      } catch (err) {}
      el.innerHTML =
        '<img src="https://api.qrserver.com/v1/create-qr-code/?size=' +
        size +
        "x" +
        size +
        "&data=" +
        encodeURIComponent(txt) +
        '" alt="Scan UPI QR Code" width="' +
        size +
        '" height="' +
        size +
        '" style="width:100%;height:100%;max-width:' +
        size +
        'px;display:block;margin:0 auto;" />';
    };
    window.QRCode.CorrectLevel = { L: 1, M: 0, Q: 3, H: 2 };
  }

  /* 4. Live Shop UPI QR Standee Updater */
  window.updateStandeeQr = function () {
    var nameEl = document.getElementById("shopNameInput");
    var catEl = document.getElementById("shopCatInput");
    var upiEl = document.getElementById("shopUpiInput");
    var amtEl = document.getElementById("shopBillAmountInput");
    var noteEl = document.getElementById("shopNoteInput");

    if (!nameEl || !upiEl) return;

    var name = (nameEl.value || "MY LOCAL BUSINESS").trim();
    var cat = catEl ? catEl.value : "VERIFIED RETAIL & KIRANA STORE";
    var upi = (upiEl.value || "uikeylabs@ybl").trim();
    var amt = amtEl ? parseFloat(amtEl.value) : 0;
    var note = noteEl ? (noteEl.value || "Scan & Pay via Any UPI App").trim() : "Scan & Pay via Any UPI App";

    var prevName = document.getElementById("previewShopName");
    var prevCat = document.getElementById("previewCategoryBadge");
    var prevUpi = document.getElementById("previewUpiText");
    var prevNote = document.getElementById("previewNoteText");
    var amtPill = document.getElementById("previewAmountPill");

    if (prevName) prevName.textContent = name;
    if (prevCat) prevCat.textContent = cat;
    if (prevUpi) prevUpi.textContent = "UPI ID: " + upi;
    if (prevNote) prevNote.textContent = note;

    var hasAmt = !isNaN(amt) && amt > 0;
    if (amtPill) {
      amtPill.textContent = hasAmt ? "Pay ₹" + amt.toLocaleString("en-IN") : "Scan & Enter Any Amount";
    }

    var upiUri =
      "upi://pay?pa=" +
      encodeURIComponent(upi) +
      "&pn=" +
      encodeURIComponent(name) +
      (hasAmt ? "&am=" + amt.toFixed(2) : "") +
      "&cu=INR";

    var payDeepLink = document.getElementById("standeeUpiDeepLink");
    if (payDeepLink) payDeepLink.href = upiUri;

    var wrap = document.getElementById("standeeQrCanvasWrap");
    if (wrap) {
      wrap.innerHTML = "";
      new window.QRCode(wrap, {
        text: upiUri,
        width: 205,
        height: 205,
        colorDark: "#0F172A",
        colorLight: "#FFFFFF",
        correctLevel: 2
      });
    }
  };

  window.printStandeePoster = function () {
    window.print();
  };

  window.speakBillHindi = function () {
    var nameEl = document.getElementById("shopNameInput");
    var amtEl = document.getElementById("shopBillAmountInput");
    var name = nameEl && nameEl.value ? nameEl.value.trim() : "हमारी दुकान";
    var amt = amtEl ? parseFloat(amtEl.value) : 0;
    var text =
      !isNaN(amt) && amt > 0
        ? "कृपया " + name + " पर " + amt + " रुपये का भुगतान करने के लिए QR कोड स्कैन करें। धन्यवाद!"
        : "कृपया " + name + " पर भुगतान करने के लिए QR कोड स्कैन करें।";
    if ("speechSynthesis" in window) {
      window.speechSynthesis.cancel();
      var u = new SpeechSynthesisUtterance(text);
      u.lang = "hi-IN";
      window.speechSynthesis.speak(u);
    }
  };

  /* 5. App-Style Multi-Tab Switcher */
  window.switchAppView = function (viewId, updateHash) {
    var panels = document.querySelectorAll(".app-view-panel");
    var targetPanel = document.getElementById("view-" + viewId);
    if (!targetPanel) {
      viewId = "home";
      targetPanel = document.getElementById("view-home");
    }
    if (!targetPanel) return;

    panels.forEach(function (panel) {
      panel.classList.remove("is-active");
    });
    targetPanel.classList.add("is-active");

    var tabBtns = document.querySelectorAll("[data-view-target]");
    tabBtns.forEach(function (btn) {
      var isMatch = btn.getAttribute("data-view-target") === viewId;
      btn.classList.toggle("active", isMatch);
      btn.setAttribute("aria-selected", isMatch ? "true" : "false");
    });

    if (viewId === "qr") {
      window.updateStandeeQr();
    }

    window.closeMobileMenu();
    window.scrollTo({ top: 0, behavior: "smooth" });

    if (updateHash !== false && history.replaceState) {
      history.replaceState(null, "", viewId === "home" ? window.location.pathname : "#" + viewId);
    }
  };

  /* 6. Mobile Navigation Drawer */
  window.toggleMobileMenu = function () {
    var menu = document.getElementById("mobile-menu");
    var btn = document.getElementById("mobileMenuTriggerBtn");
    if (!menu || !btn) return;
    var isOpen = menu.classList.toggle("is-open");
    btn.setAttribute("aria-expanded", isOpen ? "true" : "false");
  };

  window.closeMobileMenu = function () {
    var menu = document.getElementById("mobile-menu");
    var btn = document.getElementById("mobileMenuTriggerBtn");
    if (!menu || !btn) return;
    menu.classList.remove("is-open");
    btn.setAttribute("aria-expanded", "false");
  };

  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape") {
      window.closeMobileMenu();
    }
  });

  /* 7. Industry Demo Filter */
  window.filterIndustryDemos = function (category, triggerBtn) {
    var cards = document.querySelectorAll("[data-industry-card]");
    var buttons = document.querySelectorAll("[data-industry-filter]");

    buttons.forEach(function (btn) {
      var isCurrent = btn === triggerBtn;
      btn.classList.toggle("active", isCurrent);
      btn.setAttribute("aria-pressed", isCurrent ? "true" : "false");
    });

    cards.forEach(function (card) {
      var cardCats = (card.getAttribute("data-industry-card") || "").split(" ");
      if (category === "all" || cardCats.indexOf(category) !== -1) {
        card.style.display = "flex";
      } else {
        card.style.display = "none";
      }
    });
  };

  /* 8. Language Toggle (Flag-only on 360px mobile, Flag + Text on >=768px desktop) */
  var copyDict = {
    en: {
      heroBadge: "BUILT TO RANK ON GOOGLE • MOBILE-FIRST WEB ENGINEERING",
      heroTitle:
        'Turn Local Search & Mobile Visitors Into Daily Clients With <span class="text-gradient">Fast WhatsApp Lead Websites</span>',
      heroDesc:
        "Built to rank on Google with clean schema markup and sub-1s loading. Tap any tab or card below to explore 9 Live Demos, Packages, or Free Shop QR Generator."
    },
    hi: {
      heroBadge: "गूगल पर रैंक करने के लिए निर्मित • सुपर-फास्ट मोबाइल वेबसाइट",
      heroTitle:
        'अपने लोकल बिज़नेस, स्कूल, क्लिनिक या दुकान को <span class="text-gradient">तेज़ WhatsApp Lead Website</span> से ऑनलाइन बढ़ाएं',
      heroDesc:
        "बिना लंबी स्क्रॉलिंग के नीचे किसी भी कार्ड या टैब पर टैप करें—9 लाइव डेमो, वेबसाइट पैकेज और फ्री दुकान UPI QR जनरेटर तुरंत खोलें!"
    }
  };

  window.toggleSiteLanguage = function () {
    currentLang = currentLang === "en" ? "hi" : "en";
    var data = copyDict[currentLang];
    var badgeEl = document.getElementById("heroBadgeText");
    var titleEl = document.getElementById("heroMainHeading");
    var descEl = document.getElementById("heroSubHeading");
    var toggleBtns = document.querySelectorAll(".lang-flag-btn");

    if (badgeEl) badgeEl.textContent = data.heroBadge;
    if (titleEl) titleEl.innerHTML = data.heroTitle;
    if (descEl) descEl.textContent = data.heroDesc;

    toggleBtns.forEach(function (btn) {
      btn.setAttribute("aria-pressed", currentLang === "hi" ? "true" : "false");
      btn.innerHTML =
        currentLang === "hi"
          ? '<span aria-hidden="true">🌐</span><span class="lang-label-desktop">English</span>'
          : '<span aria-hidden="true">🇮🇳</span><span class="lang-label-desktop">हिंदी</span>';
    });
  };

  /* 9. Consultation Form Submission */
  window.handleConsultationSubmit = function (event) {
    event.preventDefault();
    var form = event.target;
    var statusEl = document.getElementById("leadFormStatus");
    var submitBtn = document.getElementById("leadSubmitBtn");

    var name = (form.querySelector('[name="business_name"]').value || "").trim();
    var category = (form.querySelector('[name="industry"]').value || "").trim();
    var phone = (form.querySelector('[name="mobile"]').value || "").trim();
    var city = (form.querySelector('[name="city"]').value || "").trim();

    var cleanPhone = phone.replace(/[^0-9]/g, "");
    if (!name || cleanPhone.length < 10) {
      if (statusEl) {
        statusEl.textContent = "Please enter your business name and a valid 10-digit mobile number.";
        statusEl.className = "form-status show error";
      }
      return;
    }

    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.textContent = "Opening WhatsApp...";
    }

    var waMessage =
      "नमस्ते UIKEY LABS! मैं अपने बिज़नेस के लिए WhatsApp पर Free Consultation लेना चाहता हूँ।\n\n" +
      "• Business Name: " + name + "\n" +
      "• Industry: " + category + "\n" +
      "• Mobile: " + cleanPhone + "\n" +
      "• City: " + (city || "India");

    var waUrl = "https://wa.me/918770912734?text=" + encodeURIComponent(waMessage);

    fetch("/api/leads", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ business_name: name, industry: category, mobile: cleanPhone, city: city })
    }).catch(function () {});

    if (statusEl) {
      statusEl.textContent = "✅ Inquiry ready! Redirecting you to WhatsApp for your free consultation...";
      statusEl.className = "form-status show success";
    }

    window.open(waUrl, "_blank", "noopener,noreferrer");

    setTimeout(function () {
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.textContent = "WhatsApp पर Free Consultation लें →";
      }
    }, 1200);
  };

  /* Initialize Countdown, Slots, QR & Hash Route on Load */
  document.addEventListener("DOMContentLoaded", function () {
    renderCampaignSlotsAndTimer();
    setInterval(renderCampaignSlotsAndTimer, 1000);
    window.updateStandeeQr();

    var hash = (window.location.hash || "").replace("#", "").toLowerCase();
    var map = {
      demos: "demos",
      "industry-demos": "demos",
      pricing: "pricing",
      "pricing-packages": "pricing",
      qr: "qr",
      "shop-qr": "qr",
      "merchant-qr": "qr",
      faq: "faq",
      process: "faq",
      contact: "contact",
      "free-consultation": "contact"
    };
    if (map[hash]) {
      window.switchAppView(map[hash], false);
    }
  });

  window.addEventListener("load", function () {
    renderCampaignSlotsAndTimer();
    window.updateStandeeQr();
  });
})();
